cat > /workspace/probes/gen2.js <<'JSEOF'
const { execFileSync } = require('child_process');
const fs = require('fs');
const EXE='/workspace/dataset/test13_executable', OUT='/workspace/probes/combinators.jsonl';
const D3='http://json-schema.org/draft-03/schema#',D4='http://json-schema.org/draft-04/schema#',D6='http://json-schema.org/draft-06/schema#',D7='http://json-schema.org/draft-07/schema#',D19='https://json-schema.org/draft/2019-09/schema',D20='https://json-schema.org/draft/2020-12/schema';
const DRAFTS=[D3,D4,D6,D7,D19,D20];
const pairs=[]; const add=(a,b)=>pairs.push([JSON.stringify(a),JSON.stringify(b)]);
const sweep=(a,b)=>{for(const s of DRAFTS) add(a,Object.assign({"$schema":s},b));};

add("ab",{allOf:""}); add("ab",{allOf:{}}); add("ab",{anyOf:""}); add("ab",{anyOf:{}});
add("ab",{oneOf:{}}); add("ab",{allOf:0}); add("ab",{allOf:null}); add("ab",{anyOf:true});
add("ab",{if:{type:"string"},else:1}); add("ab",{if:{type:"number"},then:1});
add("ab",{oneOf:[]}); add("ab",{anyOf:[]});
// booleans as whole schema per draft
sweep("ab", null); // placeholder replaced below
pairs.pop();pairs.pop();pairs.pop();pairs.pop();pairs.pop();pairs.pop();
for(const s of DRAFTS){ pairs.push([JSON.stringify("ab"), JSON.stringify({"$schema":s,not:{}})]); }
for(const s of DRAFTS){ pairs.push([JSON.stringify("ab"), JSON.stringify({"$schema":s,not:true})]); }
for(const s of DRAFTS){ pairs.push([JSON.stringify("ab"), JSON.stringify({"$schema":s,if:{type:"string"},then:false})]); }
// nested count bubbling deeper
add({x:{y:{z:"a"}}},{properties:{x:{properties:{y:{properties:{z:{allOf:[{minLength:9},{maxLength:0},{type:"number"}]}}}}}}});
add({a:"x",b:"x",c:"x"},{properties:{a:{allOf:[{type:"number"},{minLength:9}]},b:{allOf:[{type:"number"}]},c:{oneOf:[{type:"number"},{type:"null"}]}}});
add(["a","a","a"],{items:{oneOf:[{type:"number"},{type:"null"}]}});
add(["a","a"],{items:{allOf:[{minLength:9},{maxLength:0},{type:"number"}]}});
// allOf + sibling keywords at same level
add("ab",{type:"number",allOf:[{minLength:9},{maxLength:0}]});
add("ab",{minLength:9,allOf:[{maxLength:0}],anyOf:[{type:"number"}],oneOf:[],not:{}});
// anyOf where one branch valid but siblings fail
add("ab",{anyOf:[{type:"string"}],minLength:9});
// oneOf with 3 matches
add("ab",{oneOf:[{},{},{}]});
add("ab",{oneOf:[{}]});
// if/then/else all three, else branch multiple failures
add(5,{if:{type:"string"},then:{minLength:9},else:{minimum:10,maximum:1,multipleOf:7}});
add(5,{if:{type:"number"},then:{minimum:10,maximum:1,multipleOf:7},else:{minLength:9}});
// deeply nested combinators inside not/anyOf collapse
add("ab",{anyOf:[{properties:{}},{type:"number"}],not:{anyOf:[{type:"string"}]}});
add("ab",{not:{not:{type:"number"}}});
add("ab",{allOf:[{oneOf:[{type:"number"},{type:"null"}]},{anyOf:[{type:"number"}]},{not:{}}]});
// 2019-09/2020-12 unevaluated interplay with if/then
add({a:1,b:2},{"$schema":D19,properties:{a:{}},if:{properties:{a:{}}},then:{properties:{b:{}}},unevaluatedProperties:false});
add({a:1,b:2},{"$schema":D19,properties:{a:{}},unevaluatedProperties:false});
add({a:1,b:2},{"$schema":D19,anyOf:[{properties:{b:{}}}],properties:{a:{}},unevaluatedProperties:false});

const lines=[];
for(const [a,b] of pairs){let out='',code=0;
 try{out=execFileSync(EXE,['--a',a,'--b',b],{stdio:['ignore','pipe','ignore']}).toString();}
 catch(e){out=e.stdout?e.stdout.toString():'';code=(e.status==null)?-1:e.status;}
 lines.push(JSON.stringify({a,b,out,exit:code}));
 console.log(code, b, '=>', out.trim().replace(/\n/g,'|'));
}
fs.appendFileSync(OUT, lines.join('\n')+'\n');
console.log('appended', lines.length);
